INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'kn'), 'A2', 'yesterday', 'What I Did Yesterday', 'Talk about the past: where you went and what you did.', 'Monday morning: a colleague asks about your weekend.', 'Saying what you did ends in -e: “hode” (I went), “tinde” (I ate), “maadide” (I did). It is the same whoever is speaking.', 1, 'published', datetime('now'), datetime('now'), 1);
