INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'past-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The past: “hode”, “tinde”, “maadide”', 'What you did ends in -e: “hode” (I went), “tinde” (I ate), “maadide” (I did). With “neevu” (you, polite) it ends in -ri: “maadidri?” (did you do?), “bandri?” (did you come?). Kannada''s past is not gendered for “I” and “you”.');
