INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'future-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The future: “-tini” and “-ona”', 'In everyday Bengaluru Kannada “I will” ends in -tini: “eltini” (I''ll get up), “mugistini” (I''ll finish), “kalistini” (I''ll send). “Let''s” ends in -ona: “hogona” (let''s go), “maataadona” (let''s talk).');
