INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'polite-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Softer requests: “…tira?”', 'To ask kindly, ask whether the person will do it: “maadtira?” (would you do?), “kodtira?” (would you give?), “maataadtira?” (would you speak?). It is softer than the plain “-i” request (“kodi”, “maadi”).');
