INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'liking'), (SELECT id FROM languages WHERE code = 'en'), 'Liking things: “nanage … ishta”', 'Kannada says “to me, X is liked”: “nanage coffee ishta” (I like coffee), “ishta illa” (don''t like). “Nimage enu ishta?” asks what someone likes. It is the same whoever is speaking.');
