INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'comparing'), (SELECT id FROM languages WHERE code = 'en'), 'Comparing: “-ginta” and “-kkinta”', 'Add “-ginta” (than) to what you compare against: “bussiginta” (than the bus). After “idu” (this) and “adu” (that) it becomes “idakkinta” and “adakkinta”. Then say what is more: “kadime bele” (cheaper), “bega” (faster).');
