INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'kn'), 'B1', 'having-to', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'having-to'), (SELECT id FROM languages WHERE code = 'en'), 'Having to: “-beku”', 'Add “-beku” to a verb for what you have to or want to do: “hogbeku” (have to go), “maataadbeku” (need to speak). “Nanage … beku” on its own means “I need …”: “nanage raje beku” (I need leave).');
