INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'can-and-cant'), (SELECT id FROM languages WHERE code = 'en'), 'Can and can''t: “baratte” and “aagutte”', 'For a skill, say “nanage … baratte” (it comes to me): “nanage drive maadoke baratte” (I can drive); “baralla” is “I can''t”. For what is possible, use “-oke aagutte” and “-oke aagalla”: “baroke aagalla” (I can''t come).');
